// Background images for the admin and candidate login screens.
// Embedded as base64 (same pattern as logo.js) so no separate image upload
// to the GitHub repo is needed — just include this script tag.
//
// Re-compressed to JPEG @ ~82-85% quality from the original sources — since
// both render blurred behind the login card (see the CSS blur+overlay
// treatment in admin.html/login.html), there's no visible benefit to
// shipping full lossless size, only slower page loads.

const ADMIN_LOGIN_BG_DATA_URI = 'data:image/jpeg;base64,';
const CANDIDATE_LOGIN_BG_DATA_URI = 'data:image/jpeg;base64,';
